INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (6664, 'Ý nghĩa lá bài VII of Wands trong Tarot', 'vii-of-wands', '		<div data-elementor-type="wp-post" data-elementor-id="6664" class="elementor elementor-6664" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-20cfdc7 e-flex e-con-boxed e-con e-parent" data-id="20cfdc7" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-34220f3 e-con-full e-flex e-con e-parent" data-id="34220f3" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-8576632 elementor-widget elementor-widget-heading" data-id="8576632" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h1 class="elementor-heading-title elementor-size-default">Ý nghĩa lá bài <span style="color:#E7CD79"> VII of Wands</span></h1>				</div>
				</div>
				<div class="elementor-element elementor-element-8b5b487 elementor-widget elementor-widget-text-editor" data-id="8b5b487" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p><strong>Từ khoá đúng</strong>: bảo vệ, đứng lên bảo vệ chính mình, bảo vệ chính mình, bảo vệ lãnh thổ.</p><p><strong>Từ khoá đảo ngược</strong>: bỏ cuộc, thừa nhận thất bại, đầu hàng, thiếu tự tin, đầu hàng.</p>								</div>
				</div>
				</div>
		<div class="elementor-element elementor-element-aaf75b4 e-con-full e-flex e-con e-parent" data-id="aaf75b4" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-b6dfd32 elementor-widget elementor-widget-image" data-id="b6dfd32" data-element_type="widget" data-widget_type="image.default">
				<div class="elementor-widget-container">
															<img loading="lazy" decoding="async" width="768" height="1330" src="https://media.huynhhieutravel.com/vii-of-wands.jpg" class="attachment-full size-full wp-image-6665" alt="VII of Wands" />															</div>
				</div>
