				</div>
		<div class="elementor-element elementor-element-065bcd2 e-flex e-con-boxed e-con e-parent" data-id="065bcd2" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
