				<div class="elementor-element elementor-element-634d229 e-flex e-con-boxed e-con e-parent" data-id="634d229" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
